#!/usr/bin/env bash
# Capture an RViz screenshot reproducibly, without touching the physical display.
#
# RViz is rendered onto an Xvfb virtual framebuffer instead of the real X server.
# That makes screenshots work when the laptop screen is off or locked, keeps them at a
# fixed resolution regardless of the desktop, and means the documentation images can be
# regenerated by anyone who clones this repo.
#
# Usage:  scripts/capture_rviz.sh <rviz_config> <output.png> [settle_seconds]
#
# Must run INSIDE the container, with the simulation already running.

set -euo pipefail

CONFIG="${1:?usage: capture_rviz.sh <rviz_config> <output.png> [settle_seconds]}"
OUTPUT="${2:?usage: capture_rviz.sh <rviz_config> <output.png> [settle_seconds]}"
SETTLE="${3:-25}"
DISPLAY_NUM=":99"
RES="1600x1000x24"

source /opt/ros/jazzy/setup.bash
source ~/ros2_ws/install/setup.bash

cleanup() { kill "${RVIZ_PID:-}" "${XVFB_PID:-}" 2>/dev/null || true; }
trap cleanup EXIT

# Reuse an existing Xvfb if one is already up, otherwise start one.
if ! DISPLAY="$DISPLAY_NUM" xdpyinfo >/dev/null 2>&1; then
  Xvfb "$DISPLAY_NUM" -screen 0 "$RES" -nolisten tcp >/tmp/xvfb.log 2>&1 &
  XVFB_PID=$!
  sleep 3
fi

# LIBGL_ALWAYS_SOFTWARE: Xvfb has no GPU, so Mesa must fall back to llvmpipe.
DISPLAY="$DISPLAY_NUM" LIBGL_ALWAYS_SOFTWARE=1 \
  rviz2 -d "$CONFIG" --ros-args -p use_sim_time:=true >/tmp/rviz_capture.log 2>&1 &
RVIZ_PID=$!

echo "Waiting ${SETTLE}s for RViz to render..."
sleep "$SETTLE"

DISPLAY="$DISPLAY_NUM" scrot -o /tmp/_shot.png

# Trim the unused framebuffer border so the image is just the window.
python3 - "$OUTPUT" <<'PY'
import sys
import numpy as np
from PIL import Image

im = Image.open('/tmp/_shot.png')
a = np.array(im.convert('L'))
ys, xs = np.nonzero(a > 8)
if len(xs):
    im = im.crop((int(xs.min()), int(ys.min()), int(xs.max()) + 1, int(ys.max()) + 1))
im.save(sys.argv[1])
print(f'{sys.argv[1]}: {im.size[0]}x{im.size[1]}')
PY
